import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';

function isPositiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

function isValidDiscount(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const effectiveTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, effectiveTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!isPositiveInteger(line.qty)) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    const effectiveDiscount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (effectiveDiscount > 0) {
      newLine.discountPercent = effectiveDiscount;
    }
    invoiceLines.push(newLine);
  }

  return ok({
    customerId: normalizedId,
    issueDate,
    terms: effectiveTerms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a line (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  const discount = roundCents(lineTotal(line) * line.discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a line (lineAmount × vatRate / 100, where lineAmount = lineTotal - lineDiscount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const amount = lineTotal(line) - lineDiscount(line);
  const vat = roundCents(amount * line.vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isPositiveInteger(qty)) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }
    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const issued = {
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    number,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  };

  if (invoice.terms) {
    issued.terms = invoice.terms;
  }
  if (invoice.dueDate) {
    issued.dueDate = invoice.dueDate;
  }

  return ok(issued);
}

/**
 * Apply a voucher to an invoice (draft only, one per invoice).
 * @param {{ status: string, voucher?: Object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: Object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    voucher: { code, amount },
  });
}

